Write `factorial(n)` recursively: n × (n − 1) × … × 1, with `factorial(0)` = 1.

```js
function factorial(n) {
  // TODO: base case, then n * factorial(n - 1)
  return n;
}
```

notes.back:
// Why: Without a base case that covers 0, factorial(0) recurses forever and overflows the
// stack.
// Docs: https://developer.mozilla.org/en-US/docs/Glossary/Recursion
function factorial(n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1);
}

