**countFiles(folder)**

A folder is `{ name, files: string[], folders: Folder[] }`. Write `countFiles(folder)`: the number of files in it and every folder below it.

```js
function countFiles(folder) {
  // TODO
  return folder.files.length;
}
```

notes.back:
// Why: The base case is a folder with no sub-folders: the loop doesn't run and it returns
// its own file count.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Functions
function countFiles(folder) {
  let total = folder.files.length;
  for (const child of folder.folders) {
    total += countFiles(child);
  }
  return total;
}

